<?php /* Template Name: Onboarding */ if ( ! is_user_logged_in() ) { wp_safe_redirect( wp_login_url( get_permalink() ) ); exit; } get_header(); $step = function_exists( 'sd_core_onboarding_step' ) ? sd_core_onboarding_step() : 1; ?><main id="primary" class="sd-main sd-onboarding-main"><div class="sd-container sd-content-wrap"><div class="sd-onboarding-card"><div class="sd-onboarding-progress" aria-label="<?php esc_attr_e( 'Onboarding progress', 'social-discovery' ); ?>"><?php for ( $i = 1; $i <= 6; $i++ ) : ?><span class="<?php echo $i <= $step ? 'is-active' : ''; ?>" aria-hidden="true"></span><?php endfor; ?></div><?php if ( function_exists( 'sd_core_onboarding_handler' ) ) : ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="sd_onboarding"><input type="hidden" name="step" value="<?php echo esc_attr( $step ); ?>"><?php wp_nonce_field( 'sd_onboarding' ); ?><?php if ( 1 === $step ) { get_template_part( 'template-parts/onboarding/step-account' ); } elseif ( 2 === $step ) { get_template_part( 'template-parts/onboarding/step-profile' ); } elseif ( 3 === $step ) { get_template_part( 'template-parts/onboarding/step-avatar' ); } elseif ( 4 === $step ) { get_template_part( 'template-parts/onboarding/step-interests' ); } elseif ( 5 === $step ) { get_template_part( 'template-parts/onboarding/step-privacy' ); } else { get_template_part( 'template-parts/onboarding/step-complete' ); } ?><?php if ( $step < 6 ) : ?><div class="sd-onboarding-actions"><button class="sd-button sd-button-primary" type="submit"><?php echo 1 === $step ? esc_html__( 'Continue', 'social-discovery' ) : esc_html__( 'Save and continue', 'social-discovery' ); ?></button><button class="sd-button sd-button-outline" type="submit" name="skip" value="1"><?php esc_html_e( 'Skip for now', 'social-discovery' ); ?></button></div><?php endif; ?></form><?php else : ?><div class="sd-auth-message sd-auth-message-error" role="alert"><?php esc_html_e( 'The onboarding companion plugin is not active yet.', 'social-discovery' ); ?></div><?php endif; ?></div></div></main><?php get_footer(); ?>
